	private static NativeRouteSnapshot nativeRouteSnapshot() {
		return new NativeRouteSnapshot(LmdbNativeAggregateCompiler.COMPILED.get(),
				LmdbNativeAggregateCompiler.HOSTED_GENERIC.get(), LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get());
	}

	private static void assertSemanticNativeRoute(NativeRouteSnapshot before) {
		assertThat(LmdbNativeAccumulateJoin.BATCHES.get()).as("the generic accumulate seam remains unused").isZero();
		assertThat(LmdbNativeAccumulateJoin.FRAGMENT_EXECUTIONS.get()).isZero();
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - before.compiled()).as("semantic native root")
				.isPositive();
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(before.hostedGeneric());
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(before.islands());
	}

	private record NativeRouteSnapshot(long compiled, long hostedGeneric, long islands) {
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rows.add(String.join("|", parts));
				}
			}
		}
		return rows;
	}
